# Python Async WS Server Handler
import asyncio
import websockets

async def handler(websocket, path):
    print(f"Client connected: {path}")
    async for message in websocket:
        print(f"<< {message}")
        await websocket.send(f"Echo: {message}")

# Server Initialization
async def main_server():
    async with websockets.serve(handler, "0.0.0.0", 8765):
        await asyncio.Future()

asyncio.run(main_server())

# Python Async WS Client Connection
async def client_comm():
    uri = "ws://localhost:8765"
    async with websockets.connect(uri) as websocket:
        await websocket.send("Request Data")
        response = await websocket.recv()
        print(f">> {response}")

asyncio.run(client_comm())

# JavaScript Browser Client API
const socket = new WebSocket("wss://example.com/ws");

socket.onopen = (event) => {
    socket.send(JSON.stringify({ type: "GREET", payload: "Hello" }));
};

socket.onmessage = (event) => {
    const data = JSON.parse(event.data);
    console.log(`Type: ${data.type}`);
};

socket.onclose = (event) => {
    console.error("WS Closed:", event.code);
};

// Key WebSocket States
// socket.readyState == 0  // CONNECTING
// socket.readyState == 1  // OPEN
// socket.readyState == 2  // CLOSING
// socket.readyState == 3  // CLOSED
